#!/usr/bin/env bash\n\nset -euo pipefail\n\n# --- Configuration ---\nIMAGE_NAME="nightly-survival-quote-service:test"\nCONTAINER_NAME="quote-service-test"\nHOST_PORT=8081\nEXPECTED_JSON='{"quote":"Stay hydrated, even if the water is from a rusty pipe."}'\n\n# Clean up any previous leftovers\nif docker ps -a --format '{{.Names}}' | grep -q "${CONTAINER_NAME}"; then\n    docker rm -f ${CONTAINER_NAME} > /dev/null 2>&1 || true\nfi\n\n# Build the Docker image\ndocker build -t ${IMAGE_NAME} . > /dev/null\n\n# Run the container with DATE_OVERRIDE to make output deterministic\ndocker run -d \
    -e DATE_OVERRIDE=2023-01-01 \
    -p ${HOST_PORT}:8080 \
    --name ${CONTAINER_NAME} \
    ${IMAGE_NAME} > /dev/null\n\n# Wait a moment for the service to start\nsleep 2\n\n# Query the service\nRESPONSE=$(curl -s http://localhost:${HOST_PORT}/quote)\n\n# Verify the response matches expectation\nif [ "${RESPONSE}" = "${EXPECTED_JSON}" ]; then\n    echo "Test passed: received expected quote."\n    EXIT_CODE=0\nelse\n    echo "Test failed: expected ${EXPECTED_JSON} but got ${RESPONSE}"\n    EXIT_CODE=1\nfi\n\n# Clean up\ndocker rm -f ${CONTAINER_NAME} > /dev/null\n\nexit $EXIT_CODE\n
